// Build script — regenerates data/blog-posts.mjs and data/blog-post-template.mjs
// from the source .md files and blog/post.html. Run whenever posts or the
// template change: `node scripts/build-blog-bundle.mjs`
//
// The .mjs bundles are what /api/blog-render imports statically (so Vercel's
// edge bundler includes them). The source files remain the authoritative
// truth — this is a pure derivative.

import { readdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');

function parseFrontmatter(md) {
  const m = md.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)/);
  if (!m) return { meta: {}, body: md };
  const meta = {};
  for (const line of m[1].split('\n')) {
    const i = line.indexOf(':');
    if (i < 0) continue;
    const key = line.slice(0, i).trim();
    const raw = line.slice(i + 1).trim();
    if (raw.startsWith('[') && raw.endsWith(']')) {
      meta[key] = raw.slice(1, -1).split(',').map(s => s.trim().replace(/^["']|["']$/g, ''));
    } else {
      meta[key] = raw.replace(/^["']|["']$/g, '');
    }
  }
  return { meta, body: m[2].trim() };
}

async function main() {
  const contentDir = join(ROOT, 'content', 'blog');
  const files = (await readdir(contentDir)).filter(f => f.endsWith('.md'));

  const posts = {};
  for (const file of files) {
    const raw = await readFile(join(contentDir, file), 'utf8');
    const { meta, body } = parseFrontmatter(raw);
    const slug = meta.slug || file.replace(/\.md$/, '');
    posts[slug] = {
      title:       meta.title || slug,
      description: meta.description || '',
      date:        meta.date || '',
      image:       meta.image || '',
      author:      meta.author || 'NordInvest',
      lang:        meta.lang || 'en',
      tags:        Array.isArray(meta.tags) ? meta.tags : [],
      translation: meta.translation || null,
    };
  }

  const bundleOut = `// AUTO-GENERATED by scripts/build-blog-bundle.mjs — do not edit by hand.
export default ${JSON.stringify(posts, null, 2)};
`;
  await writeFile(join(ROOT, 'data', 'blog-posts.mjs'), bundleOut);
  console.log(`✓ data/blog-posts.mjs — ${Object.keys(posts).length} posts`);

  // Also embed the current post.html template as a raw string module so the
  // edge bundler includes it.
  const template = await readFile(join(ROOT, 'blog', 'post.html'), 'utf8');
  const templateOut = `// AUTO-GENERATED by scripts/build-blog-bundle.mjs — do not edit by hand.
// Source of truth: blog/post.html
export default ${JSON.stringify(template)};
`;
  await writeFile(join(ROOT, 'data', 'blog-post-template.mjs'), templateOut);
  console.log(`✓ data/blog-post-template.mjs — ${template.length} bytes`);
}

main().catch(e => { console.error(e); process.exit(1); });
